import {calendarInventory,calendarInventoryHtml} from './calendar-inventory.js';
import {recordsCalendarEvents} from './case-records.js';
function formalMilestones(p){return (p.familySituations?.length?p.familySituations:[p]).flatMap((s,n)=>[...(s.children?.length?s.children.map((c,i)=>['birth-'+i,'Narodziny: '+(c.name||'dziecko '+(i+1)),c.birthDate]):[['birth','Narodziny',s.childBirthDate]]),['placement','Przyjęcie na wychowanie'+(s.name?': '+s.name:''),s.placementDate],['adoption','Prawomocność adopcji'+(s.name?': '+s.name:''),s.adoptionCourtDate],['due','Przewidywany termin porodu',s.caseStage==='pregnancy'?s.eventDate:'']].filter(([, ,date])=>date).map(([id,title,date])=>({id:'family-'+n+'-'+id,title,start:date,end:date,type:'birth',description:'Data podana w sytuacji rodzinnej. Planowane zdarzenie nie potwierdza nabycia prawa.'})));}
import {scopeCatalog} from './source-scope.js';
import {todayString,shiftDate,dayNumber} from './age.js';
import {datedEvents,milestones,weekOnDate,overlaps,sourceLink,pregnancyStart,birthDate} from './timeline.js';
import {EVENT_GROUPS,taskDisposition,sortTasks} from './event-policy.js';
import {quantity,ordinal,calendarDate,periodText} from './polish.js';
import {createNotesStore,pinSvg} from './notes.js';
import {createNotesView,dayPinsHtml} from './notes-view.js';
import {calculatorCalendarEvents} from './calculator-storage.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const importantIcon=()=>'<svg class="important-icon" viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M14 5c1-2 3-2 4 0l12 21c1 2 0 3-2 3H4c-2 0-3-1-2-3Z" fill="#eefef7" stroke="#1dca81" stroke-width="2.4" stroke-linejoin="round"/><path d="M16 11v8" stroke="#1dca81" stroke-width="3" stroke-linecap="round"/><circle cx="16" cy="24" r="1.7" fill="#1dca81"/></svg>';
export const refreshIcon=()=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/></svg>';
const dateText=calendarDate;
const rangeText=periodText;
const taskIcon=event=>event.required?importantIcon():`<svg class="event-neutral-icon ${event.group}" viewBox="0 0 28 28" fill="none" aria-hidden="true">${event.group==='optional'?'<rect x="4" y="7" width="20" height="16" rx="4"/><path d="M8 7V5h12v2M4 13h20m-11 4h2"/>':'<path d="M14 23 5 14C-1 7 9 1 14 8c5-7 15-1 9 6Z"/>'}</svg>`;
const taskLabel=event=>`${event.required?'Obowiązkowe':event.group==='optional'?'Dodatkowe':'Zalecane'} · ${event.kind}`;
export function createPlanner({getProfile,persist,sheetContent,notify,notesStore=createNotesStore(),calculatorStore=null,recordsStore=null,openRecords=()=>{},openCalculator=()=>{}}) {
  let state=null,offline=false,selected=todayString(),month=selected.slice(0,7),onChange=()=>{},inventory=[];
  const notesView=createNotesView({store:notesStore,sheetContent,notify,onChanged:date=>{selected=date;month=date.slice(0,7);onChange();requestAnimationFrame(()=>{const view=document.querySelector('#calendar-view'),agenda=view?.querySelector('.calendar-agenda');if(view&&agenda)view.scrollTo({top:view.scrollTop+agenda.getBoundingClientRect().top-view.getBoundingClientRect().top-15,behavior:'smooth'});});}});
  async function load(){try{const r=await fetch('/api/catalog',{cache:'no-store'});if(!r.ok)throw new Error();state=await r.json();offline=false;}catch{if(!state){const r=await fetch('data/catalog.json');state={catalog:scopeCatalog(await r.json()),sources:{},sourceScope:'zus'};}offline=true;}return state;}
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state)load().then(()=>{if(getProfile())onChange();});});
  setInterval(()=>{if(!document.hidden&&state)load().then(()=>{if(getProfile())onChange();});},120000);
  const events=(date=todayString())=>state?[...datedEvents(state.catalog,getProfile(),date),...(calculatorStore?calculatorCalendarEvents(calculatorStore.snapshot(),state.calculatorRules,date,recordsStore?.snapshot()):[]),...recordsCalendarEvents(recordsStore?.snapshot())]:[];
  function card(event){return `<button class="event-card group-${event.group} ${event.important&&event.required?'is-important':''} ${event.done?'is-done':''} ${event.notApplicable?'is-not-applicable':''}" data-event="${event.id}" data-group="${event.group}"><span class="event-symbol">${event.notApplicable?'—':event.done?'✓':taskIcon(event)}</span><span><small>${esc(taskLabel(event))}${event.notApplicable?' · Nie dotyczy':event.done?' · Oznaczone jako wykonane':''}</small><strong>${esc(event.title)}</strong><span>${event.preview?(event.mode==='planning'?'Bez określonego terminu':'Termin zależy od przyszłych dat'):esc(rangeText(event))}</span>${event.important?`<b>${event.daysLeft===0?'Termin przypada dzisiaj':`Do końca okresu: ${quantity(event.daysLeft,'days')}`}</b>`:''}${event.needsDate&&!event.notApplicable?'<b>Potrzebna dodatkowa data</b>':''}</span><span class="event-chevron">›</span></button>`;}
  function groupedTasks(items,render=card,heading=4){
    const active=items.filter(e=>!e.notApplicable),excluded=sortTasks(items.filter(e=>e.notApplicable));
    return EVENT_GROUPS.map(group=>{const cards=sortTasks(active.filter(e=>e.group===group.id));return cards.length?`<section class="task-group task-group-${group.id}" data-task-group="${group.id}"><h${heading}>${esc(group.title)}<span>${cards.length}</span></h${heading}><p class="task-group-description">${esc(group.description)}</p>${cards.map(render).join('')}</section>`:'';}).join('')+(excluded.length?`<details class="excluded-tasks"><summary>Oznaczone jako „Nie dotyczy” (${excluded.length})</summary><p class="field-help">Te sprawy nie są wyróżniane w kalendarzu. Otwórz kartę, aby cofnąć oznaczenie.</p>${excluded.map(card).join('')}</details>`:'');
  }
  function bind(container){container.querySelectorAll('[data-event]').forEach(button=>button.addEventListener('click',()=>openEvent(button.dataset.event)));}
  function openEvent(id,contextEvent=null){
    const e=contextEvent||events(month+'-01').find(e=>e.id===id);if(!e)return;
    if(e.recordId){sheetContent('Wpis z mojego rejestru','<h3>'+esc(e.title)+'</h3><p>'+esc(rangeText(e))+'</p><p>'+esc(e.description)+'</p><button class="secondary" id="record-calendar-open">Otwórz i popraw wpis</button>');document.querySelector('#record-calendar-open').onclick=()=>openRecords(e.recordKind);return;}
    const sourceState=state.sources?.[e.source.id],changed=sourceState&&sourceState.status!=='ok';
    sheetContent('Twoje sprawy',`<article class="event-detail"><div class="event-kind group-${e.group}">${taskIcon(e)}${esc(taskLabel(e))}</div><h3>${esc(e.title)}</h3><div class="event-range"><span class="event-range-label">${e.timing==='preparation'?'Kiedy o tym pamiętać':'Okres w kalendarzu'}</span>${e.preview?'Podgląd — bez ustalonego terminu':esc(periodText(e,{long:true}))}</div><p>${esc(e.description)}</p>${e.formalRule?`<section class="official-source"><h4>Znaczenie terminu</h4><p>Od czego liczymy: ${esc(e.formalRule.anchor)}.</p><p>Adresat: ${esc(e.formalRule.recipient)}.</p><p>${esc(e.formalRule.effect)}</p><small>${esc(e.legalBasis||'')}</small></section>`:''}${e.needsDate&&!e.notApplicable?'<button class="secondary" id="event-dates">Uzupełnij daty do terminów</button>':''}${e.timing!=='preparation'&&e.end&&e.daysLeft<0&&!e.done&&!e.notApplicable?'<p class="source-notice">Wskazany okres już minął. Sprawdź w źródle, co nadal możesz zrobić; nie każdy termin oznacza utratę całego uprawnienia.</p>':''}${changed?`<p class="source-notice">${sourceState.status==='changed'?'W źródle wykryto zmianę. Opis oczekuje na ponowną weryfikację.':sourceState.status==='missing'?'Oficjalna strona jest obecnie niedostępna. Zachowano ostatni zatwierdzony opis.':'Nie udało się teraz sprawdzić źródła. Korzystasz z ostatniego zatwierdzonego opisu.'}</p>`:''}<div class="official-source"><small>${esc(e.source.name)} · sekcja: ${esc(e.source.section)}</small><a class="secondary" href="${esc(sourceLink(e.source))}" target="_blank" rel="noopener noreferrer">Otwórz oficjalny fragment ↗</a><p class="field-help">Podświetlenie fragmentu zależy od przeglądarki i treści strony. Jeśli nie zadziała, znajdź wskazaną sekcję.</p><small>Wersja treści: ${esc(state.catalog.version)} · weryfikacja redakcyjna: ${esc(calendarDate(state.catalog.reviewedAt,{long:true}))}</small></div>${e.notApplicable?'<p class="not-applicable-notice">Oznaczono jako „Nie dotyczy”. Ta sprawa nie jest wyróżniana jako zadanie do zrobienia.</p>':''}${!e.preview&&!e.informational?`<button id="event-done" class="primary">${e.done?'Cofnij oznaczenie wykonania':'Oznacz jako wykonane'}</button>`:''}${e.canMarkNotApplicable&&!e.preview&&!e.informational?`<button id="event-not-applicable" class="secondary not-applicable-action">${e.notApplicable?'Cofnij oznaczenie „Nie dotyczy”':'Nie dotyczy'}</button>`:''}${!e.preview&&!e.informational?'<p class="field-help">To Twoje oznaczenie. Nie jest potwierdzeniem z urzędu ani placówki.</p>':''}</article>`);
    document.querySelector('#event-dates')?.addEventListener('click',openDates);
    if(e.calculatorCase){document.querySelector('.event-detail').insertAdjacentHTML('beforeend','<button class="primary" id="open-calculator-case">Otwórz zapisany scenariusz w kalkulatorze</button>');document.querySelector('#open-calculator-case').onclick=()=>{document.querySelector('#sheet').close();openCalculator(e.calculatorCase);};}
    document.querySelector('#event-done')?.addEventListener('click',()=>{persist(taskDisposition(getProfile(),e,e.done?'pending':'done'));onChange();openEvent(id);});
    document.querySelector('#event-not-applicable')?.addEventListener('click',()=>{persist(taskDisposition(getProfile(),e,e.notApplicable?'pending':'not-applicable'));onChange();openEvent(id);});
  }
  function openDates(){
    const p=getProfile(),isChild=p.mode==='child';
    const field=(id,label,value='',help='')=>`<label class="field-label" for="${id}">${label}</label><input type="date" id="${id}" name="${id}" value="${esc(value)}">${help?`<p class="field-help">${help}</p>`:''}`;
    sheetContent('Daty w kalendarzu',`<form id="dates-form" class="dates-form" novalidate><p>Uzupełnij tylko znane daty. Brakujące terminy urzędowe pozostaną oznaczone jako wymagające daty.</p>${isChild?field('pregnancyStart','Początek liczenia ciąży (opcjonalnie)',p.pregnancyStart||''):field('dueDate','Przewidywany termin porodu',p.dueDate||'','Jeśli pozostawisz puste, pokażemy orientacyjny termin po 40 tygodniach.')}${field('conceptionDate','Data poczęcia, jeśli została ustalona',p.conceptionDate||'','Puste pole oznacza tylko orientacyjny tydzień, gdy znamy początek liczenia ciąży.')}${isChild?`<label class="field-label" for="birthTime">Godzina urodzenia (opcjonalnie)</label><input id="birthTime" name="birthTime" type="time" value="${esc(p.birthTime)}">${field('birthCardDate','Data wystawienia karty urodzenia',p.dates.birthCardDate||'')}${field('peselDate','Data nadania PESEL',p.dates.peselDate||'')}${field('parentalLeaveDate','Planowany początek urlopu rodzicielskiego',p.dates.parentalLeaveDate||'')}`:''}<p class="error" id="dates-error" role="alert"></p><button class="primary" type="submit">Zapisz daty</button></form>`);
    const form=document.querySelector('#dates-form');form.addEventListener('submit',event=>{event.preventDefault();try{
      const values=Object.fromEntries(new FormData(form));for(const [key,date]of Object.entries(values)){if(date&&key!=='birthTime')dayNumber(date);}
      for(const key of ['birthCardDate','peselDate'])if(values[key]&&(values[key]<p.anchor||values[key]>todayString()))throw new Error('Data karty lub PESEL musi przypadać między narodzinami a dzisiaj.');
      if(values.pregnancyStart&&values.pregnancyStart>p.anchor)throw new Error('Początek ciąży nie może przypadać po narodzinach.');
      if(values.conceptionDate&&(values.conceptionDate>todayString()||isChild&&values.conceptionDate>p.anchor))throw new Error('Sprawdź datę poczęcia.');
      persist({...(!isChild?{dueDate:values.dueDate}:{pregnancyStart:values.pregnancyStart,birthTime:values.birthTime}),conceptionDate:values.conceptionDate,dates:{...p.dates,...Object.fromEntries(['birthCardDate','peselDate','parentalLeaveDate'].filter(k=>k in values).map(k=>[k,values[k]]))}});onChange();notify('Zapisano daty kalendarza.');document.querySelector('#sheet').close();
    }catch(error){document.querySelector('#dates-error').textContent=error.message;}});
  }
  function calendarHtml(){
    const p=getProfile(),all=events(getProfile().planning?month+'-01':todayString()),marks=p.formal?formalMilestones(p):milestones(p),noteState=notesStore.snapshot(),first=month+'-01',day=new Date(first+'T12:00Z').getUTCDay(),gridStart=shiftDate(first,-((day+6)%7)),last=shiftDate(new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),1)).toISOString().slice(0,10),-1);
    const heading=new Intl.DateTimeFormat('pl-PL',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(first+'T12:00Z'));
    let cells='';for(let i=0;i<42;i++){
      const date=shiftDate(gridStart,i),week=p.formal?null:weekOnDate(p,date),active=all.filter(e=>!e.done&&!e.notApplicable&&overlaps(e,date,date)),mark=marks.find(m=>overlaps(m,date,date)),dayNotes=noteState.notes.filter(note=>note.date===date);
      cells+=`<button class="calendar-day ${date.slice(0,7)!==month?'other-month':''} ${selected===date?'selected':''} ${date===todayString()?'today':''} ${week?`week-${week.mode}`:''} ${mark?`milestone-${mark.type}`:''} ${active.length?'has-period':''} ${dayNotes.length?'has-note':''}" data-day="${date}" aria-label="${dateText(date)}${week?`, ${ordinal(week.week,'weeks')} ${week.mode==='child'?'życia':'ciąży'}`:''}${active.length?`, ${quantity(active.length,'matters')}`:''}${dayNotes.length?`, ${quantity(dayNotes.length,'notes')}`:''}" aria-pressed="${selected===date}"><span>${Number(date.slice(8))}</span><small>${week?`${week.week}${week.mode==='child'?'ż':'c'}`:'&nbsp;'}</small><i>${mark?'◆':active.length?'●':''}</i>${dayPinsHtml(dayNotes)}</button>`;
    }
    const items=all.filter(e=>!e.notApplicable&&overlaps(e,selected,selected)),selectedMarks=marks.filter(m=>overlaps(m,selected,selected));
    inventory=calendarInventory(all,marks,noteState.notes);
    return `<div class="calendar-layout"><div class="calendar-month"><div class="calendar-top"><div><span class="eyebrow">Twój kalendarz</span><h2>${esc(heading)}</h2></div><button class="text-button" id="calendar-today">Dzisiaj</button></div><div class="calendar-controls"><button class="icon-button" id="month-prev" aria-label="Poprzedni miesiąc">‹</button><input type="month" id="month-picker" aria-label="Wybierz miesiąc" value="${month}"><button class="icon-button" id="month-next" aria-label="Następny miesiąc">›</button></div><div class="calendar-weekdays">${['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${cells}</div><div class="calendar-legend">${p.formal?'':'<span><i class="pregnancy-dot"></i>Tygodnie ciąży (c)</span><span><i class="child-dot"></i>Tygodnie życia (ż)</span>'}<span><i class="period-dot"></i>Okres na sprawę</span><span>◆ Ważna data</span><span>${pinSvg('red')}Twoje notatki</span></div><button id="calendar-dates" class="settings-row" ${p.planning||p.formal?'hidden':''}><span>Uzupełnij daty kalendarza<small>Poród, początek ciąży i terminy urzędowe</small></span>›</button></div><div class="calendar-detail"><section class="calendar-agenda"><div class="day-agenda-heading"><h3>${dateText(selected)}</h3><button class="note-add" id="note-add"><span aria-hidden="true">＋</span>Dodaj notatkę</button></div>${notesView.dayHtml(selected,noteState)}${p.planning&&!p.formal?`<section class="planning-preparation"><h3>Przygotowania bez sztywnego terminu</h3>${events().filter(e=>e.mode==='planning'&&e.preview).map(card).join('')}</section>`:''}${selectedMarks.map(m=>`<button class="milestone-card" data-milestone="${m.id}"><strong>${esc(m.title)}</strong><span>${esc(rangeText(m))}</span></button>`).join('')}${items.length?groupedTasks(items):!selectedMarks.length?'<p class="field-help">Brak spraw przypisanych do tego dnia.</p>':''}</section>${all.some(e=>e.needsDate&&!e.notApplicable)?`<section class="calendar-agenda"><h3>Terminy wymagające dodatkowej daty</h3>${groupedTasks(all.filter(e=>e.needsDate&&!e.notApplicable))}</section>`:''}${all.some(e=>e.notApplicable)?`<section class="calendar-agenda">${groupedTasks(all.filter(e=>e.notApplicable))}</section>`:''}${calendarInventoryHtml(inventory)}</div></div>`;
  }
  function bindCalendar(container){
    const rerender=()=>{container.innerHTML=calendarHtml();bindCalendar(container);};
    container.querySelectorAll('[data-inventory]').forEach(button=>button.onclick=()=>{const item=inventory[Number(button.dataset.inventory)];if(!item)return;selected=item.date;month=item.date.slice(0,7);rerender();if(item.type==='note')notesView.openNote(item.id);else if(item.type==='milestone')container.querySelector('[data-milestone="'+item.id+'"]')?.click();else openEvent(item.id,item.event);});
    notesView.bind(container,selected);
    container.querySelectorAll('[data-day]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.day;month=selected.slice(0,7);rerender();}));
    for(const [id,delta]of [['month-prev',-1],['month-next',1]])container.querySelector('#'+id).addEventListener('click',()=>{const d=new Date(month+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month=d.toISOString().slice(0,7);selected=month+'-01';rerender();});
    container.querySelector('#month-picker').addEventListener('change',event=>{if(/^\d{4}-\d{2}$/.test(event.target.value)){month=event.target.value;selected=month+'-01';rerender();}});
    container.querySelector('#calendar-today').addEventListener('click',()=>{selected=todayString();month=selected.slice(0,7);rerender();});
    container.querySelector('#calendar-dates').addEventListener('click',openDates);bind(container);
    container.querySelectorAll('[data-milestone]').forEach(b=>b.addEventListener('click',()=>{const m=(getProfile().formal?formalMilestones(getProfile()):milestones(getProfile())).find(m=>m.id===b.dataset.milestone);sheetContent('Ważna data',`<article class="event-detail"><h3>${esc(m.title)}</h3><p class="event-range">${rangeText(m)}</p><p>${esc(m.description)}</p>${m.url?`<a class="secondary" href="${m.url}" target="_blank" rel="noopener noreferrer">Jak liczymy wiek ciąży ↗</a>`:''}</article>`);}));
  }
  function refresh(){
    sheetContent('Odśwież informacje','<p>Wybierzcie, z jakich instytucji mają pochodzić materiały kalkulatora i kalendarza.</p><button class="primary" id="refresh-zus">Tylko materiały ZUS</button><button class="secondary" id="refresh-all">Wszystkie instytucje</button><p class="field-help">Pozostałe źródła pozostają zachowane. Aktualny zakres: '+(state?.sourceScope==='all'?'wszystkie instytucje':'ZUS')+'.</p>');
    document.querySelector('#refresh-zus').addEventListener('click',()=>runRefresh('zus'));document.querySelector('#refresh-all').addEventListener('click',()=>runRefresh('all'));
  }
  async function runRefresh(scope){
    const button=document.querySelector('#refresh-sources');if(button)button.disabled=true;
    const choices=[...document.querySelectorAll('#refresh-zus,#refresh-all')];choices.forEach(b=>b.disabled=true);
    const selected=document.querySelector(scope==='all'?'#refresh-all':'#refresh-zus');if(selected)selected.textContent='Sprawdzamy oficjalne źródła…';
    try{const r=await fetch('/api/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope})});if(!r.ok)throw new Error('Nie udało się odświeżyć źródeł.');state=await r.json();offline=false;onChange();openStatus();}catch(e){notify(e.message);}finally{const b=document.querySelector('#refresh-sources');if(b)b.disabled=false;choices.forEach(b=>b.disabled=false);if(selected)selected.textContent=scope==='all'?'Wszystkie instytucje':'Tylko materiały ZUS';}
  }
  function openStatus(){
    if(!state)return;
    const labels={ok:'Sprawdzono',changed:'Zmiana do weryfikacji',missing:'Źródło zniknęło',unavailable:'Nie udało się sprawdzić'};
    sheetContent('Aktualność informacji',`<p>Sprawdzanie codziennie o <strong>00:00 · Europe/Warsaw</strong>, również gdy aplikacja jest zamknięta.</p><p class="field-help">Ostatnia próba: ${state.lastCheckedAt?new Date(state.lastCheckedAt).toLocaleString('pl-PL'):'jeszcze nie uruchomiono'}. Następna: ${state.nextCheckAt?new Date(state.nextCheckAt).toLocaleString('pl-PL'):'najbliższa północ'}.</p>${offline?'<p class="source-notice">Brak połączenia z serwerem. Widoczna jest zapisana wersja treści.</p>':''}<p class="field-help">Zmiana strony, nowy dokument lub usunięty link trafia do przeglądu. Zatwierdzone terminy pozostają dostępne do czasu sprawdzenia nowych zasad.</p><div class="source-list">${state.catalog.sources.map(s=>{const status=state.sources?.[s.id];return `<div><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><span>${esc(labels[status?.status]||'Oczekuje na pierwsze sprawdzenie')}</span>${status?.newLinks?.length?`<small>Nowe dokumenty: ${status.newLinks.length}</small>`:''}</div>`;}).join('')}</div><a class="text-button" href="/admin.html" target="_blank" rel="noopener noreferrer">Panel weryfikacji treści ↗</a>`);
  }
  return {load,events,bind,calendarHtml,bindCalendar,openDates,openEvent,openNote:notesView.openNote,refresh,openStatus,setOnChange:fn=>onChange=fn};
}
